    const v = text(value, ['path', 'resource'].includes(key) ? 240 : 180);
    if (v) event[key] = key === 'decision' ? v.toUpperCase() : v;
  }
}
const evidenceAllow = new Set(['event_count', 'distinct_users', 'retry_count', 'denied_calls',
  'failed_attempts', 'success_after_failures', 'window_seconds', 'correlation_window_seconds',
  'after_event', 'prior_event_type', 'lock_request_id', 'trigger_event_type', 'timezone', 'local_time']);
