  .sort((a,b) => String(b.last_seen || '').localeCompare(String(a.last_seen || '')));
const pendingMap = sd.pendingActions && typeof sd.pendingActions === 'object' && !Array.isArray(sd.pendingActions) ? sd.pendingActions : {};
