  const plans = Object.values(pendingMap).filter(p => p && p.ticket_id === ticket.id && ['pending', 'executing'].includes(p.status));
  ticket.pending_approval = plans.some(p => p.status === 'pending');
  ticket.pending_actions = plans.map(p => ({ plan_id: p.plan_id, assessment_id: p.assessment_id,
