const now = new Date().toISOString();
const ipOk = ip => /^(?:\d{1,3}\.){3}\d{1,3}$/.test(String(ip || ''));
const res = (http, body) => [{ json: { http, body } }];
const userOk = u => /^[A-Za-z][A-Za-z0-9._-]{0,49}$/.test(String(u || ''));
