const LABEL = { applied: '적용', no_change: '변경 없음', 'dry-run': '미실행(dry-run)', error: '오류' };
const addRec = (t, rec) => { t.responses = (t.responses || []).concat([rec]).slice(-30); };
const parseDbJson = (v, fallback) => {
  if (Array.isArray(v) || (v && typeof v === 'object')) return v;
  if (typeof v === 'string') { try { return JSON.parse(v); } catch {} }
  return fallback;
};
