    last_seen:input.ticket_db_last_seen,latest:parseDbJson(input.ticket_db_latest,{}),responses};
  const makeAction=(action,resolution=null,note='',response=null,whitelist=false)=>({id:dbId,action,resolution,note,
    response:response?JSON.stringify(response):null,whitelist,whitelist_ip:t.src_ip,
    params:[dbId,action,resolution||'',String(note||'').slice(0,500),response?JSON.stringify(response):null]});
  if (b.action === 'approve_response') {
    const assessmentId = String(b.assessment_id || '').trim();
    const planId = String(b.plan_id || (assessmentId + ':' + String(b.ticket_id || ''))).trim();
    const plan = sd.pendingActions && sd.pendingActions[planId];
    if (!plan || !assessmentId || plan.assessment_id !== assessmentId || plan.ticket_id !== b.ticket_id)
      return res(404, { status: 'no_pending_action' });
    if (plan.response_group === 'session_ai')
      return res(501, { status: 'not_supported_yet', note: '세션 종료·AI Tool 제한 승인은 다음 단계에서 지원' });
    if (plan.assessment_status !== 'PENDING' || plan.approval_allowed !== true || plan.auto_allowed !== false ||
        !['DAYTIME_APPROVAL', 'WEEKEND_APPROVAL'].includes(plan.policy_reason) ||
        plan.rule_id !== 'R1' || plan.response_group !== 'lock' || plan.plan_id !== planId)
      return res(409, { status: 'invalid_pending_action' });
