    const expectedVerify = "SELECT 'lock' AS step_key, username, pinned, locked_until, (locked_until IS NOT NULL AND locked_until > NOW()) AS locked, session_version FROM users WHERE username = $1";
    if (plan.step !== '계정 잠금(AI-XDR 관제 승인)' || plan.sql !== expectedSql || plan.verify_sql !== expectedVerify ||
        !Array.isArray(plan.params) || plan.params.length !== 2 || Number(plan.params[0]) !== 15 || plan.params[1] !== plan.user)
      return res(409, { status: 'invalid_pending_plan' });
