        detail: '승인만 기록; 실제 계정 잠금 미실행', assessment_id: assessmentId,
        ticket_id: plan.ticket_id, plan_id: planId
      };
      return [{json: {
        xdr_decision_request: { assessment_id: assessmentId, status: 'APPROVED', approval_ref: planId },
        ticket_id: plan.ticket_id, ticket_response_exists: responseExists, pending_plan_id: planId,
        db_ticket_action: responseExists ? undefined : makeAction('record_response', null, '', approvalRecord)
      }}];
    }
    plan.status = 'executing';
    plan.last_attempt_at = now;
    return [{ json: { http: 200, body: null, db: {
